package com.wontlost.ckeditor.collaboration;

import tools.jackson.databind.JsonNode;

import java.io.Serializable;
import java.time.Instant;
import java.util.Objects;

/**
 * A comment, as stored (CKEditor {@code CommentData}).
 *
 * @param commentId  the comment id (generated by CKEditor)
 * @param authorId   the author's user id, always set by the server
 * @param createdAt  the creation time, always set by the server
 * @param content    the comment content (HTML)
 * @param attributes custom attributes ({@code {}} if none)
 * @since 6.2.0
 */
public record CommentData(String commentId, String authorId, Instant createdAt, String content,
                          JsonNode attributes) implements Serializable {

    /**
     * @throws NullPointerException if an id, the time or the content is null
     */
    public CommentData {
        Objects.requireNonNull(commentId, "commentId");
        Objects.requireNonNull(authorId, "authorId");
        Objects.requireNonNull(createdAt, "createdAt");
        Objects.requireNonNull(content, "content");
        attributes = Json.objectOrEmpty(attributes);
    }

    /**
     * @param content the new content
     * @return a copy with the content replaced
     */
    public CommentData withContent(String content) {
        return new CommentData(commentId, authorId, createdAt, content, attributes);
    }

    /**
     * @param attributes the new attributes
     * @return a copy with the attributes replaced
     */
    public CommentData withAttributes(JsonNode attributes) {
        return new CommentData(commentId, authorId, createdAt, content, attributes);
    }
}
